// 保留 Marked 官方 UMD 入口，附加中文强调兼容扩展，浏览器和 Node 测试共用同一产物。
const fs = require('node:fs');
const path = require('node:path');
const { build } = require('esbuild');

async function buildMarkdownVendor() {
    const root = path.resolve(__dirname, '..');
    const markedRoot = path.dirname(require.resolve('marked/package.json'));
    const cjkRoot = path.dirname(require.resolve('marked-cjk-friendly/package.json'));
    const core = fs.readFileSync(path.join(markedRoot, 'lib/marked.umd.js'), 'utf8')
        .replace(/^\/\/# sourceMappingURL=.*$/gm, '').trimEnd();
    const licenses = [markedRoot, cjkRoot].map(dir => fs.readFileSync(path.join(dir, 'LICENSE'), 'utf8'));
    const result = await build({
        stdin: {
            contents: `export { default } from 'marked-cjk-friendly';`,
            resolveDir: root,
            sourcefile: 'marked-cjk-setup.js',
        },
        bundle: true,
        format: 'iife',
        globalName: 'NoteCjkFriendly',
        minify: true,
        write: false,
    });
    fs.writeFileSync(path.join(root, 'public/vendor/marked.min.js'),
        `${core}\n\n/*!\n * Generated by npm run build:markdown; do not edit.\n${licenses.join('\n')}\n */\n(function () {\n${result.outputFiles[0].text}\nconst parser = typeof module !== 'undefined' && module.exports ? module.exports : globalThis.marked;\nparser.use(NoteCjkFriendly.default());\n})();\n`);
}

if (require.main === module) {
    buildMarkdownVendor().catch(error => { console.error(error); process.exitCode = 1; });
}

module.exports = { buildMarkdownVendor };
